def test_integrate_retries_auth_with_askpass_fallback(monkeypatch):
    module = load_dispatcher()
    calls = []

    def fake_git(*args, **kwargs):
        if args[:3] == ("config", "--local", "--get"):
            return SimpleNamespace(returncode=0, stdout="store --file=/safe/credentials\n")
        if args[:2] == ("rev-parse", "origin/Edarsahub_Desarrollo"):
            return SimpleNamespace(returncode=0, stdout="base\n")
        return SimpleNamespace(returncode=0, stdout="")

    def fake_run(args, **kwargs):
        calls.append((args, kwargs))
        if "push" in args and any("credential.helper=store" in x for x in args):
            return SimpleNamespace(returncode=128, stdout="fatal: could not read Username for https://github.com: terminal prompts disabled")
        return SimpleNamespace(returncode=0, stdout="ok")

    monkeypatch.setattr(module, "git", fake_git)
    monkeypatch.setattr(module, "run", fake_run)

    module.integrate("candidate", "base")

    pushes = [args for args, _ in calls if "push" in args]
    assert len(pushes) == 2
    assert any("credential.helper=store --file=/safe/credentials" in x for x in pushes[0])
    assert "credential.helper=" in pushes[1]
    assert not any("credential.helper=store" in x for x in pushes[1])
